<?php
require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';[$period,$from,$to,$branch,$brand]=page_params();$type=$_GET['type']??'sales';$valid=['sales','inventory','receiving','usage','wastage','transfers'];if(!in_array($type,$valid,true))$type='sales';
$c=[];$a=[];if($branch){$c[]='branch_id=?';$a[]=$branch;}if($brand){$c[]='brand_id=?';$a[]=$brand;}
if($type==='sales'){$c[]='sale_date BETWEEN ? AND ?';$a[]=$from;$a[]=$to;$sql='SELECT reference_no,sale_date AS report_date,branch_id,brand_id,total_amount AS value,status FROM sales WHERE deleted_at IS NULL AND '.implode(' AND ',$c).' ORDER BY sale_date DESC';}
elseif($type==='inventory'){$sql='SELECT p.name product,b.name branch,br.name brand,SUM(it.quantity_in) quantity_in,SUM(it.quantity_out) quantity_out,SUM(it.quantity_in-it.quantity_out) balance FROM inventory_transactions it JOIN products p ON p.id=it.product_id JOIN branches b ON b.id=it.branch_id JOIN brands br ON br.id=it.brand_id '.($c?'WHERE '.implode(' AND ',array_map(fn($x)=>'it.'.$x,$c)):'').' GROUP BY p.id,it.branch_id,it.brand_id ORDER BY p.name';}
else{$map=['receiving'=>['stock_receivings','received_date','total_cost'],'usage'=>['stock_usages','usage_date','NULL'],'wastage'=>['wastages','wastage_date','cost_impact'],'transfers'=>['stock_transfers','transfer_date','NULL']];[$table,$date,$value]=$map[$type];$c[]="$date BETWEEN ? AND ?";$a[]=$from;$a[]=$to;if($type==='transfers'){$c=array_map(fn($x)=>str_replace('branch_id','from_branch_id',$x),$c);}$sql="SELECT reference_no,$date report_date,".($type==='transfers'?'from_branch_id branch_id':'branch_id').",brand_id,$value value,status FROM $table WHERE deleted_at IS NULL AND ".implode(' AND ',$c)." ORDER BY $date DESC";}
$s=$pdo->prepare($sql);$s->execute($a);$rows=$s->fetchAll();
if(($_GET['export']??'')==='csv'){require_permission('reports.export');audit($pdo,'export','reports');header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="'.$type.'-report-'.date('Ymd').'.csv"');$out=fopen('php://output','w');if($rows){fputcsv($out,array_keys($rows[0]));foreach($rows as $r)fputcsv($out,$r);}fclose($out);exit;}
$branches=array_column(options($pdo,'branches'),'label','id');$brands=array_column(options($pdo,'brands'),'label','id');render_header('Reports','reports');page_title('Reports Center','ANALYTICS & EXPORTS','Filter, review, print and export operational records.');
?><div class="card" style="margin-bottom:20px"><form class="filters"><select name="type" data-auto-submit><?php foreach($valid as $v):?><option value="<?=$v?>"<?=selected($type,$v)?>><?=e(ucfirst($v))?> Report</option><?php endforeach;?></select><select name="period" data-auto-submit><option value="today"<?=selected($period,'today')?>>Today</option><option value="7days"<?=selected($period,'7days')?>>Last 7 Days</option><option value="30days"<?=selected($period,'30days')?>>Last 30 Days</option><option value="month"<?=selected($period,'month')?>>This Month</option><option value="year"<?=selected($period,'year')?>>This Year</option></select><select name="branch" data-auto-submit><option value="0">All Branches</option><?php foreach($branches as $id=>$label):?><option value="<?=$id?>"<?=selected($branch,$id)?>><?=e($label)?></option><?php endforeach;?></select><select name="brand" data-auto-submit><option value="0">All Brands</option><?php foreach($brands as $id=>$label):?><option value="<?=$id?>"<?=selected($brand,$id)?>><?=e($label)?></option><?php endforeach;?></select><a class="btn" href="?<?=e(http_build_query(array_merge($_GET,['export'=>'csv'])))?>">Export CSV / Excel</a><button type="button" class="btn" onclick="print()">Print / PDF</button></form></div><div class="grid stats"><article class="stat"><div class="stat-head"><span>REPORT TYPE</span></div><strong><?=e(ucfirst($type))?></strong><span class="trend">Operational dataset</span></article><article class="stat" style="--accent:#17b783"><div class="stat-head"><span>RECORDS</span></div><strong><?=number_format(count($rows))?></strong><span class="trend">Matching filters</span></article><article class="stat" style="--accent:#2f80ed"><div class="stat-head"><span>FROM</span></div><strong style="font-size:18px"><?=date('d M Y',strtotime($from))?></strong></article><article class="stat" style="--accent:#ef476f"><div class="stat-head"><span>TO</span></div><strong style="font-size:18px"><?=date('d M Y',strtotime($to))?></strong></article></div><article class="card table-card"><div class="table-toolbar"><div><b><?=e(ucfirst($type))?> Report</b><small style="display:block;color:var(--muted);margin-top:4px">Generated <?=date('d M Y, H:i')?></small></div></div><div class="table-wrap"><table><thead><tr><?php if($type==='inventory'):?><th>Product</th><th>Branch</th><th>Brand</th><th>In</th><th>Out</th><th>Balance</th><?php else:?><th>Reference</th><th>Date</th><th>Branch</th><th>Brand</th><th>Value</th><th>Status</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php if($type==='inventory'):?><td data-label="Product"><?=e($r['product'])?></td><td data-label="Branch"><?=e($r['branch'])?></td><td data-label="Brand"><?=e($r['brand'])?></td><td data-label="In"><?=number_format($r['quantity_in'],3)?></td><td data-label="Out"><?=number_format($r['quantity_out'],3)?></td><td data-label="Balance"><b><?=number_format($r['balance'],3)?></b></td><?php else:?><td data-label="Reference"><b><?=e($r['reference_no'])?></b></td><td data-label="Date"><?=date('d M Y',strtotime($r['report_date']))?></td><td data-label="Branch"><?=e($branches[$r['branch_id']]??$r['branch_id'])?></td><td data-label="Brand"><?=e($brands[$r['brand_id']]??$r['brand_id'])?></td><td data-label="Value"><?=$r['value']!==null?money($r['value']):'—'?></td><td data-label="Status"><span class="status"><?=e(ucfirst($r['status']))?></span></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></article><?php render_footer('reports');
